// server/services/seed.service.ts
var seedDefaults = async (db) => {
  const marker = await db.query(
    "select value from settings where key = 'seeded'"
  );
  if (marker.length > 0) return;
  await db.transaction(async (tx) => {
    for (const [key, value] of Object.entries(defaultSettings)) {
      await tx.query(
        `insert into settings (key, value) values ($1, $2::jsonb)
         on conflict (key) do nothing`,
        [key, json(value)]
      );
    }
    for (const page of defaultPages) {
      await tx.query(
        `insert into pages (id, title, content, seo_title, seo_description)
         values ($1, $2, $3::jsonb, $4, $5)
         on conflict (id) do nothing`,
        [page.id, page.title, json(page.content), page.seoTitle, page.seoDescription]
      );
    }
    for (const link of defaultNavLinks) {
      await tx.query(
        `insert into nav_links (id, label, href, location, external, sort_order, visible)
         values ($1, $2, $3, $4, $5, $6, $7)`,
        [
          randomUUID2(),
          link.label,
          link.href,
          link.location,
          link.external,
          link.sortOrder,
          link.visible
        ]
      );
    }
    for (const skill of defaultSkills) {
      await tx.query(
        `insert into skills (id, name, category, icon, proficiency, sort_order, visible)
         values ($1, $2, $3, $4, $5, $6, true)`,
        [
          randomUUID2(),
          skill.name,
          skill.category,
          skill.icon || null,
          skill.proficiency,
          skill.sortOrder
        ]
      );
    }
    for (const item of defaultExperiences) {
      await tx.query(
        `insert into experiences (id, kind, company, position, description, period, link, sort_order, visible)
         values ($1, $2, $3, $4, $5, $6, $7, $8, true)`,
        [
          randomUUID2(),
          item.kind,
          item.company,
          item.position,
          item.description,
          item.period,
          item.link,
          item.sortOrder
        ]
      );
    }
    for (const service of defaultServices) {
      await tx.query(
        `insert into services (id, title, description, icon, price, sort_order, visible)
         values ($1, $2, $3, $4, $5, $6, true)`,
        [
          randomUUID2(),
          service.title,
          service.description,
          service.icon,
          service.price,
          service.sortOrder
        ]
      );
    }
    for (const project of defaultProjects) {
      await tx.query(
        `insert into projects
           (id, slug, title, summary, description, cover_url, gallery, category, tags,
            repo_url, live_url, featured, status, sort_order, published_at)
         values ($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9::jsonb,$10,$11,$12,$13,$14,
            case when $13 = 'published' then now() else null end)`,
        [
          randomUUID2(),
          project.slug,
          project.title,
          project.summary,
          project.description,
          project.coverUrl,
          json(project.gallery),
          project.category,
          json(project.tags),
          project.repoUrl,
          project.liveUrl,
          project.featured,
          project.status,
          project.sortOrder
        ]
      );
    }
    await tx.query(
      `insert into settings (key, value) values ('seeded', 'true'::jsonb)
       on conflict (key) do nothing`
    );
  });
};

// server/routes/audit.ts
import { Hono } from "hono";

// server/lib/validation.ts
var parseJson = async (c, schema) => {
  let body;
  try {
    body = await c.req.json();
  } catch {
    throw badRequest("Invalid JSON body");
  }
  const result = schema.safeParse(body);
  if (!result.success) {
    throw new AppError(400, "validation_error", "Validation failed", result.error.flatten());
  }
  return result.data;
};
var parseQuery = (c, schema) => {
  const result = schema.safeParse(c.req.query());
  if (!result.success) {
    throw new AppError(400, "validation_error", "Invalid query parameters", result.error.flatten());
  }
  return result.data;
};

// server/services/audit.service.ts
var recordAudit = async (input, db) => {
  const client = db ?? await getDb();
  await client.query(
    `insert into audit_logs
       (admin_id, admin_email, action, entity_type, entity_id, metadata, ip)
     values ($1, $2, $3, $4, $5, $6::jsonb, $7)`,
    [
      input.adminId ?? null,
      input.adminEmail ?? null,
      input.action,
      input.entityType ?? null,
      input.entityId ?? null,
      input.metadata ? json(input.metadata) : null,
      input.ip ?? null
    ]
  );
};
var listAuditLogs = async (limit = 50) => {
  const db = await getDb();
  return db.query(
    `select id, admin_email, action, entity_type, entity_id, metadata, ip, created_at
     from audit_logs
     order by created_at desc
     limit $1`,
    [Math.min(Math.max(limit, 1), 200)]
  );
};

// server/routes/audit.ts
var querySchema = external_exports.object({
  limit: external_exports.coerce.number().int().min(1).max(200).optional()
});
var auditRoutes = new Hono();
auditRoutes.get("/", async (c) => {
  const { limit } = parseQuery(c, querySchema);
  return c.json({ items: await listAuditLogs(limit) });
});

