import { Hono as Hono5 } from "hono";

// server/storage/local.ts
import { mkdir, rm, writeFile, readFile } from "node:fs/promises";
import { dirname, join, normalize, resolve, sep } from "node:path";
var baseDir = resolve(process.cwd(), env.storage.localDir);
var resolveLocalPath = (key) => {
  const safeKey = normalize(key).replace(/^([.]{2}[/\\])+/, "");
  const full = resolve(baseDir, safeKey);
  if (full !== baseDir && !full.startsWith(baseDir + sep)) {
    throw new Error("Invalid storage key");
  }
  return full;
};
var localStorage = {
  name: "local",
  async put({ key, body }) {
    const full = resolveLocalPath(key);
    await mkdir(dirname(full), { recursive: true });
    await writeFile(full, body);
    return { key, url: `${env.storage.publicPrefix}/${key}` };
  },
  async delete(key) {
    const full = resolveLocalPath(key);
    await rm(full, { force: true });
  },
  publicUrl(key) {
    return `${env.storage.publicPrefix}/${key}`;
  },
  async read(key) {
    return readFile(resolveLocalPath(key));
  }
};

// server/routes/files.ts
var CONTENT_TYPES = {
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  avif: "image/avif",
  gif: "image/gif",
  svg: "image/svg+xml"
};
var contentTypeFor = (key) => {
  const extension = key.split(".").pop()?.toLowerCase() ?? "";
  return CONTENT_TYPES[extension] ?? "application/octet-stream";
};
var filesRoutes = new Hono5();
filesRoutes.get("/:key{.+}", async (c) => {
  if (env.storage.driver !== "local") {
    return c.notFound();
  }
  const key = c.req.param("key");
  try {
    const buffer = await localStorage.read(key);
    return c.body(new Uint8Array(buffer), 200, {
      "Content-Type": contentTypeFor(key),
      "Cache-Control": "public, max-age=31536000, immutable"
    });
  } catch {
    return c.notFound();
  }
});

// server/routes/media.ts
import { Hono as Hono6 } from "hono";

// server/services/media.service.ts
import { randomUUID as randomUUID4 } from "node:crypto";
import sharp from "sharp";

// server/storage/vercel-blob.ts
import { del, put } from "@vercel/blob";
var blobStorage = {
  name: "vercel-blob",
  async put({ key, body, contentType }) {
    const result = await put(key, body, {
      access: "public",
      contentType,
      addRandomSuffix: false,
      token: env.storage.blobToken
    });
    return { key, url: result.url };
  },
  async delete(key) {
    await del(key, { token: env.storage.blobToken });
  },
  publicUrl(key) {
    return key;
  }
};

// server/storage/index.ts
var getStorage = () => env.storage.driver === "vercel-blob" ? blobStorage : localStorage;
var buildStorageKey = (extension) => {
  const now = /* @__PURE__ */ new Date();
  const yyyy = now.getUTCFullYear();
  const mm = String(now.getUTCMonth() + 1).padStart(2, "0");
  const id = globalThis.crypto.randomUUID();
  return `media/${yyyy}/${mm}/${id}.${extension}`;
};

// server/services/media.service.ts
var mapMedia = (row) => ({
  id: row.id,
  url: row.url,
  storageKey: row.storage_key,
  filename: row.filename,
  mimeType: row.mime_type,
  sizeBytes: row.size_bytes,
  width: row.width,
  height: row.height,
  format: row.format,
  createdAt: row.created_at
});
var MIME_BY_FORMAT = {
  jpeg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  avif: "image/avif"
};
var processImage = async (input) => {
  const maxBytes = input.maxBytes ?? env.uploads.maxFileSizeBytes;
  const maxDimension = input.maxDimension ?? env.uploads.maxDimension;
  const allowed = input.allowedFormats ?? env.uploads.allowedFormats;
  if (input.buffer.length === 0) throw badRequest("Empty file");
  if (input.buffer.length > maxBytes) {
    throw new AppError(413, "file_too_large", "File exceeds the maximum size");
  }
  let pipeline;
  try {
    pipeline = sharp(input.buffer, { failOn: "error" });
  } catch {
    throw badRequest("Unsupported or corrupt image");
  }
  const metadata = await pipeline.metadata().catch(() => {
    throw badRequest("Unsupported or corrupt image");
  });
  const format = metadata.format;
  if (!format || !allowed.includes(format)) {
    throw badRequest(`Unsupported image format. Allowed: ${allowed.join(", ")}`);
  }
  const width = metadata.width ?? 0;
  const height = metadata.height ?? 0;
  if (width === 0 || height === 0) throw badRequest("Invalid image dimensions");
  if (width > maxDimension || height > maxDimension) {
    throw badRequest(`Image dimensions must not exceed ${maxDimension}px`);
  }
  const options = format === "png" ? { compressionLevel: 9 } : format === "avif" ? { quality: 55 } : { quality: 82, mozjpeg: format === "jpeg" };
  const output = await sharp(input.buffer).rotate().toFormat(format, options).toBuffer();
  return {
    buffer: output,
    format,
    mimeType: MIME_BY_FORMAT[format] ?? `image/${format}`,
    width,
    height
  };
};
var storeImage = async (input) => {
  const processed = await processImage({ buffer: input.file.buffer });
  const storage = getStorage();
  const key = buildStorageKey(processed.format === "jpeg" ? "jpg" : processed.format);
  const { url: url2 } = await storage.put({
    key,
    body: processed.buffer,
    contentType: processed.mimeType
  });
  const db = await getDb();
  const id = randomUUID4();
  const safeName = input.file.originalName.replace(/[^\w.-]+/g, "_").slice(0, 120) || "image";
  const rows = await db.query(
    `insert into media
       (id, storage_key, url, filename, mime_type, size_bytes, width, height, format)
     values ($1,$2,$3,$4,$5,$6,$7,$8,$9)
     returning *`,
    [
      id,
      key,
      url2,
      safeName,
      processed.mimeType,
      processed.buffer.length,
      processed.width,
      processed.height,
      processed.format
    ]
  );
  return mapMedia(rows[0]);
};
var listMedia = async (options) => {
  const db = await getDb();
  const page = Math.max(1, options.page ?? 1);
  const pageSize = Math.min(100, Math.max(1, options.pageSize ?? 24));
  const conditions = [];
  const params = [];
  if (options.search) {
    params.push(`%${options.search.toLowerCase()}%`);
    conditions.push(`lower(filename) like $${params.length}`);
  }
  const where = conditions.length ? `where ${conditions.join(" and ")}` : "";
  const countRows = await db.query(
    `select count(*)::text as count from media ${where}`,
    params
  );
  params.push(pageSize);
  const limitIdx = params.length;
  params.push((page - 1) * pageSize);
  const offsetIdx = params.length;
  const rows = await db.query(
    `select * from media ${where} order by created_at desc
     limit $${limitIdx} offset $${offsetIdx}`,
    params
  );
  return {
    items: rows.map(mapMedia),
    total: Number(countRows[0]?.count ?? 0),
    page,
    pageSize
  };
};
var getMedia = async (id) => {
  const db = await getDb();
  const rows = await db.query("select * from media where id = $1", [id]);
  return rows[0] ? mapMedia(rows[0]) : null;
};
var isMediaReferenced = async (url2) => {
  const db = await getDb();
  const rows = await db.query(
    `select (
       (select count(*) from projects where cover_url = $1)
       + (select count(*) from skills where icon = $1)
       + (select count(*) from services where icon = $1)
       + (select count(*) from projects where gallery @> $2::jsonb)
     )::text as count`,
    [url2, json([url2])]
  );
  return Number(rows[0]?.count ?? 0) > 0;
};
var deleteMedia = async (id) => {
  const media = await getMedia(id);
  if (!media) throw new AppError(404, "not_found", "Media not found");
  if (await isMediaReferenced(media.url)) {
    throw new AppError(
      409,
      "media_in_use",
      "This image is used by existing content and cannot be deleted."
    );
  }
  await getStorage().delete(media.storageKey);
  const db = await getDb();
  await db.query("delete from media where id = $1", [id]);
};

// server/routes/media.ts
var listQuerySchema = external_exports.object({
  page: external_exports.coerce.number().int().min(1).optional(),
  pageSize: external_exports.coerce.number().int().min(1).max(100).optional(),
  search: external_exports.string().trim().max(120).optional()
});
var mediaRoutes = new Hono6();
mediaRoutes.get("/", async (c) => {
  const query = parseQuery(c, listQuerySchema);
  return c.json(await listMedia(query));
});
mediaRoutes.get("/:id", async (c) => {
  const media = await getMedia(c.req.param("id"));
  if (!media) throw notFound("Media not found");
  return c.json(media);
});
mediaRoutes.post("/", async (c) => {
  const session = c.get("session");
  const ip = getClientIp(c);
  await consumeRateLimit(
    "upload:ip",
    ip,
    env.rateLimit.uploadMaxRequests,
    env.rateLimit.uploadWindowSeconds
  );
  const body = await c.req.parseBody();
  const raw = body["file"];
  const files = (Array.isArray(raw) ? raw : [raw]).filter(
    (entry) => entry instanceof File
  );
  if (files.length === 0) throw badRequest("No file provided");
  if (files.length > env.uploads.maxFilesPerRequest) {
    throw badRequest(`Too many files (max ${env.uploads.maxFilesPerRequest})`);
  }
  const totalBytes = files.reduce((sum, file2) => sum + file2.size, 0);
  if (totalBytes > env.uploads.maxTotalBytes) throw badRequest("Upload is too large");
  const items = [];
  for (const file2 of files) {
    const buffer = Buffer.from(await file2.arrayBuffer());
    if (buffer.length > env.uploads.maxFileSizeBytes) {
      throw badRequest(`"${file2.name}" exceeds the maximum file size`);
    }
    const media = await storeImage({ file: { buffer, originalName: file2.name } });
    items.push(media);
    await recordAudit({
      adminId: session.admin.id,
      adminEmail: session.admin.email,
      action: "media.uploaded",
      entityType: "media",
      entityId: media.id,
      metadata: { filename: media.filename, size: media.sizeBytes },
      ip
    });
  }
  return c.json({ items }, 201);
});
mediaRoutes.delete("/:id", async (c) => {
  const session = c.get("session");
  const id = c.req.param("id");
  await deleteMedia(id);
  await recordAudit({
    adminId: session.admin.id,
    adminEmail: session.admin.email,
    action: "media.deleted",
    entityType: "media",
    entityId: id,
    ip: getClientIp(c)
  });
  return c.json({ ok: true });
});

