// server/routes/projects.ts
import { Hono as Hono8 } from "hono";

// server/services/projects.service.ts
import { randomUUID as randomUUID6 } from "node:crypto";
var slugSchema = external_exports.string().trim().toLowerCase().min(1, "Slug is required").max(80, "Slug is too long").regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "Slug may contain lowercase letters, numbers and hyphens");
var urlOrNull = external_exports.string().trim().max(2048).refine(
  (value) => value === "" || /^https?:\/\/.+/i.test(value) || value.startsWith("/"),
  "Enter a valid URL"
).nullable().optional().transform((value) => value ? value : null);
var projectInputSchema = external_exports.object({
  title: external_exports.string().trim().min(2, "Title is required").max(160),
  slug: slugSchema.optional(),
  summary: external_exports.string().trim().max(300).default(""),
  description: external_exports.string().trim().max(2e4).default(""),
  coverUrl: urlOrNull,
  coverMediaId: external_exports.string().uuid().nullable().optional(),
  gallery: external_exports.array(external_exports.string().trim().max(2048)).max(30).default([]),
  category: external_exports.string().trim().max(80).default("General"),
  tags: external_exports.array(external_exports.string().trim().min(1).max(40)).max(30).default([]),
  repoUrl: urlOrNull,
  liveUrl: urlOrNull,
  featured: external_exports.boolean().default(false),
  status: external_exports.enum(["draft", "published"]).default("draft"),
  sortOrder: external_exports.number().int().min(0).max(1e5).optional(),
  startDate: external_exports.string().trim().max(40).nullable().optional(),
  endDate: external_exports.string().trim().max(40).nullable().optional(),
  seoTitle: external_exports.string().trim().max(200).nullable().optional(),
  seoDescription: external_exports.string().trim().max(300).nullable().optional()
});
var toArray = (value) => Array.isArray(value) ? value.map((entry) => String(entry)) : [];
var mapProject = (row) => ({
  id: row.id,
  slug: row.slug,
  title: row.title,
  summary: row.summary,
  description: row.description,
  coverMediaId: row.cover_media_id,
  coverUrl: row.cover_url,
  gallery: toArray(row.gallery),
  category: row.category,
  tags: toArray(row.tags),
  repoUrl: row.repo_url,
  liveUrl: row.live_url,
  featured: row.featured,
  status: row.status,
  sortOrder: row.sort_order,
  startDate: row.start_date,
  endDate: row.end_date,
  seoTitle: row.seo_title,
  seoDescription: row.seo_description,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
  publishedAt: row.published_at
});
var slugify2 = (value) => value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "project";
var ensureUniqueSlug = async (slug, excludeId) => {
  const db = await getDb();
  let candidate = slug;
  let suffix = 1;
  while (true) {
    const rows = await db.query(
      "select id from projects where slug = $1",
      [candidate]
    );
    const conflict = rows.find((row) => row.id !== excludeId);
    if (!conflict) return candidate;
    suffix += 1;
    candidate = `${slug}-${suffix}`.slice(0, 80);
    if (suffix > 500) throw badRequest("Unable to generate a unique slug");
  }
};
var listProjects = async (options) => {
  const db = await getDb();
  const page = Math.max(1, options.page ?? 1);
  const pageSize = Math.min(100, Math.max(1, options.pageSize ?? 20));
  const conditions = [];
  const params = [];
  if (options.status) {
    params.push(options.status);
    conditions.push(`status = $${params.length}`);
  }
  if (options.category) {
    params.push(options.category);
    conditions.push(`category = $${params.length}`);
  }
  if (options.search) {
    params.push(`%${options.search.toLowerCase()}%`);
    conditions.push(`lower(title) like $${params.length}`);
  }
  const where = conditions.length ? `where ${conditions.join(" and ")}` : "";
  const countRows = await db.query(
    `select count(*)::text as count from projects ${where}`,
    params
  );
  params.push(pageSize);
  const limitIdx = params.length;
  params.push((page - 1) * pageSize);
  const offsetIdx = params.length;
  const rows = await db.query(
    `select * from projects ${where}
     order by sort_order asc, created_at desc
     limit $${limitIdx} offset $${offsetIdx}`,
    params
  );
  return {
    items: rows.map(mapProject),
    total: Number(countRows[0]?.count ?? 0),
    page,
    pageSize
  };
};
var listPublishedProjects = async () => {
  const db = await getDb();
  const rows = await db.query(
    `select * from projects where status = 'published'
     order by sort_order asc, published_at desc`
  );
  return rows.map(mapProject);
};
var getProjectById = async (id) => {
  const db = await getDb();
  const rows = await db.query("select * from projects where id = $1", [id]);
  return rows[0] ? mapProject(rows[0]) : null;
};
var getPublishedProjectBySlug = async (slug) => {
  const db = await getDb();
  const rows = await db.query(
    "select * from projects where slug = $1 and status = 'published'",
    [slug]
  );
  return rows[0] ? mapProject(rows[0]) : null;
};
var createProject = async (input) => {
  const db = await getDb();
  const baseSlug = input.slug ? slugSchema.parse(input.slug) : slugify2(input.title);
  const slug = await ensureUniqueSlug(baseSlug);
  const id = randomUUID6();
  const sortOrder2 = input.sortOrder ?? Date.now() % 1e5;
  const rows = await db.query(
    `insert into projects
       (id, slug, title, summary, description, cover_media_id, cover_url, gallery,
        category, tags, repo_url, live_url, featured, status, sort_order,
        start_date, end_date, seo_title, seo_description, published_at)
     values ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10::jsonb,$11,$12,$13,$14,$15,
             $16,$17,$18,$19,
             case when $14 = 'published' then now() else null end)
     returning *`,
    [
      id,
      slug,
      input.title,
      input.summary,
      input.description,
      input.coverMediaId ?? null,
      input.coverUrl,
      json(input.gallery),
      input.category,
      json(input.tags),
      input.repoUrl,
      input.liveUrl,
      input.featured,
      input.status,
      sortOrder2,
      input.startDate ?? null,
      input.endDate ?? null,
      input.seoTitle ?? null,
      input.seoDescription ?? null
    ]
  );
  return mapProject(rows[0]);
};
var updateProject = async (id, input) => {
  const db = await getDb();
  const existing = await getProjectById(id);
  if (!existing) throw new AppError(404, "not_found", "Project not found");
  const baseSlug = input.slug ? slugSchema.parse(input.slug) : slugify2(input.title);
  const slug = await ensureUniqueSlug(baseSlug, id);
  const rows = await db.query(
    `update projects set
       slug = $2, title = $3, summary = $4, description = $5,
       cover_media_id = $6, cover_url = $7, gallery = $8::jsonb,
       category = $9, tags = $10::jsonb, repo_url = $11, live_url = $12,
       featured = $13, status = $14, sort_order = $15,
       start_date = $16, end_date = $17, seo_title = $18, seo_description = $19,
       published_at = case
         when $20 = 'published' and published_at is null then now()
         when $20 = 'draft' then null
         else published_at
       end,
       updated_at = now()
     where id = $1
     returning *`,
    [
      id,
      slug,
      input.title,
      input.summary,
      input.description,
      input.coverMediaId ?? null,
      input.coverUrl,
      json(input.gallery),
      input.category,
      json(input.tags),
      input.repoUrl,
      input.liveUrl,
      input.featured,
      input.status,
      input.sortOrder ?? 0,
      input.startDate ?? null,
      input.endDate ?? null,
      input.seoTitle ?? null,
      input.seoDescription ?? null,
      input.status
    ]
  );
  return mapProject(rows[0]);
};
var updateProjectStatus = async (id, status) => {
  const db = await getDb();
  const rows = await db.query(
    `update projects set
       status = $2,
       published_at = case
         when $2 = 'published' and published_at is null then now()
         when $2 = 'draft' then null
         else published_at
       end,
       updated_at = now()
     where id = $1
     returning *`,
    [id, status]
  );
  if (!rows[0]) throw new AppError(404, "not_found", "Project not found");
  return mapProject(rows[0]);
};
var updateProjectFeatured = async (id, featured) => {
  const db = await getDb();
  const rows = await db.query(
    "update projects set featured = $2, updated_at = now() where id = $1 returning *",
    [id, featured]
  );
  if (!rows[0]) throw new AppError(404, "not_found", "Project not found");
  return mapProject(rows[0]);
};
var reorderProjects = async (orderedIds) => {
  const db = await getDb();
  await db.transaction(async (tx) => {
    for (let index = 0; index < orderedIds.length; index += 1) {
      await tx.query("update projects set sort_order = $2, updated_at = now() where id = $1", [
        orderedIds[index],
        index
      ]);
    }
  });
};
var deleteProject = async (id) => {
  const db = await getDb();
  const rows = await db.query("delete from projects where id = $1 returning id", [id]);
  if (rows.length === 0) throw new AppError(404, "not_found", "Project not found");
};

